<?php use Namira\{StoreCart,StoreSettings,Db,Security,MobileAuth};$items=StoreCart::items($db,$user);$settings=StoreSettings::get($db);$old=$_SESSION['commerce_feedback']['input']??[];unset($_SESSION['commerce_feedback']);$physical=false;$total=0;$errors=false; ?>
<link rel="stylesheet" href="/assets/store.css?v=010"><h1>سبد خرید</h1><?php if(!$items): ?><p class="empty">سبد خرید خالی است.</p><a class="primary" href="<?= e(url('shop')) ?>">مشاهده محصولات</a><?php else: ?>
<?php foreach($items as $i):$errors=$errors||$i['error']!=='';$physical=$physical||(!$i['error']&&$i['product']['delivery']!=='digital');$total+=$i['price']*$i['quantity']; ?><article class="panel"><h2><?= e($i['product']['title']??'محصول غیرفعال') ?></h2><?php if($i['error']): ?><p class="notice notice-error"><?= e($i['error']) ?></p><?php else: ?><p><?= e($i['variant']['attributes']) ?> · <?= fa(number_format($i['price'])) ?> تومان × <?= fa($i['quantity']) ?></p><?php if((int)$i['quoted_price']!==$i['price']): ?><p class="notice">قیمت تغییر کرده است؛ مبلغ فعلی نمایش داده شده است.</p><?php endif ?><dl><?php foreach($i['data']['form']['fields']??[] as $f):$v=$i['data']['values'][$f['key']]??'';if(in_array($f['type'],['image','file'],true)):foreach((array)$v as $fid): ?><a class="outline" href="<?= e(url('store-file',['id'=>$fid,'preview'=>1])) ?>">پیوست <?= e($f['label']) ?></a><?php endforeach;else: ?><dt><?= e($f['label']) ?></dt><dd><?= e(is_array($v)?implode('، ',$v):$v) ?></dd><?php endif;endforeach ?></dl><a href="<?= e(url('product',['id'=>$i['product']['id'],'line'=>$i['id']])) ?>">ویرایش گزینه‌ها و اطلاعات اختصاصی</a><?php endif ?><form method="post" class="store-inline"><?= Security::field() ?><input type="hidden" name="action" value="commerce-quantity"><input type="hidden" name="id" value="<?= (int)$i['id'] ?>"><label>تعداد (صفر برای حذف)<input name="quantity" type="number" min="0" max="99" value="<?= (int)$i['quantity'] ?>"></label><button class="outline">به‌روزرسانی</button></form></article><?php endforeach ?>
<section class="panel"><h2>تسویه‌حساب</h2><p>جمع کالاها: <?= fa(number_format($total)) ?> تومان</p><p class="muted">هزینه ارسال، مالیات و تخفیف پس از انتخاب نشانی و روش ارسال، در صورت‌حساب نهایی پیش از پرداخت نمایش داده می‌شوند.</p>
<?php if(!$user||!MobileAuth::verified($db,$user)): ?><a class="primary" href="<?= e(url('member-login',['next_page'=>'cart'])) ?>">ورود و ادامه خرید</a>
<?php elseif(!$settings['enable_sales']||!trim($settings['sales_terms'])): ?><p class="notice">فروشگاه تا تکمیل تنظیمات فروش، سفارش جدید نمی‌پذیرد.</p>
<?php elseif(Namira\Env::get('PAYMENT_DRIVER')!=='test'||Namira\Env::get('APP_ENV')==='production'): ?><p class="notice">درگاه واقعی هنوز پیکربندی نشده؛ ثبت پرداخت فعال نیست.</p>
<?php else: ?><p class="notice">پرداخت آزمایشی است و وجه واقعی جابه‌جا نمی‌شود.</p><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="commerce-checkout"><input type="hidden" name="checkout_key" value="<?= e($_SESSION['checkout_key']??=bin2hex(random_bytes(32))) ?>"><div class="fields"><label>نام گیرنده / خریدار<input name="customer" required value="<?= e($old['customer']??'') ?>"></label><label>شماره همراه<input name="phone" required value="<?= e($old['phone']??Namira\MobileAuth::identity($db,(int)$user['id'])['mobile']??'') ?>"></label>
<?php if($physical): ?><label>نشانی ذخیره‌شده<select name="address_id"><option value="">نشانی جدید</option><?php foreach(Db::query($db,'SELECT id,title FROM account_addresses WHERE user_id=?',[$user['id']])->fetchAll() as $address): ?><option value="<?= (int)$address['id'] ?>"><?= e($address['title']) ?></option><?php endforeach ?></select></label><?php foreach(['province'=>'استان','city'=>'شهر','postal_code'=>'کدپستی'] as $k=>$label): ?><label><?= $label ?><input name="<?= $k ?>" value="<?= e($old[$k]??'') ?>" <?= $k!=='postal_code'?'required':'' ?>></label><?php endforeach ?><label class="field full">نشانی کامل<textarea name="address" maxlength="2000"><?= e($old['address']??'') ?></textarea></label><label>روش ارسال<select name="shipping_method" required><option value="">انتخاب کنید</option><?php foreach($settings['shipping'] as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['title']) ?> · هزینه پایه <?= fa(number_format($s['base'])) ?> تومان</option><?php endforeach ?></select></label><?php endif ?><label>کد تخفیف<input name="discount_code" value="<?= e($old['discount_code']??'') ?>"></label></div><label class="store-check"><input type="checkbox" name="accept_price_changes" value="1">قیمت‌های فعلی نمایش‌داده‌شده را تأیید می‌کنم.</label><details><summary>شرایط فروش</summary><p class="prose"><?= nl2br(e($settings['sales_terms'])) ?></p></details><button class="primary" <?= $errors?'disabled':'' ?>>ثبت سفارش و مشاهده صورت‌حساب پرداخت</button></form><?php endif ?></section><?php endif ?>
